 'xp_exp': lambda p,x: p[0]*x**p[1]*np.exp(-p[2]*x),
 'tanh_exp': lambda p,x: p[0]*np.tanh(p[1]*x)*np.exp(-p[2]*x),
 'x_expq': lambda p,x: p[0]*x*np.exp(-p[1]*x**2),
 'x_sin': lambda p,x: p[0]*np.sin(p[1]*x)*np.exp(-p[2]*x),
 'sat_lin': lambda p,x: p[0]*x/(1+p[1]*x**p[2]),
 'x_over': lambda p,x: p[0]*x/(p[1]+x**p[2]),
}
res={}
for name,f in fams.items():
